/**
 * Funcref-wrapper struct / func-type registry for js2wasm closures.
 *
 * Extracted verbatim from `closures.ts` (issue #3270) — the small, foundational
 * wrapper-struct / lifted-func-type registry that the method-trampoline and
 * funcref-as-closure subsystems both build on. Isolates the isorecursive
 * root-wrapper canonicalization logic (#2873) in one place.
 */

import type { ClosureInfo, CodegenContext } from "../context/types.js";
import type { ValType } from "../../ir/types.js";
import { ts } from "../../ts-api.js";
import { funcSignatureOf } from "../func-space.js"; // (#1916 S2 read chokepoint)
import { addFuncType } from "../registry/types.js";
import { closureArityField, closureBagField } from "./closure-header-layout.js";

export type ClosureAllocationMode = "support" | "ordinary" | "host-one-shot";

function observeAllocation(info: ClosureInfo, mode: ClosureAllocationMode): void {
  if (mode === "ordinary") info.hostOneShotOnly = false;
  else if (mode === "host-one-shot" && info.hostOneShotOnly === undefined) info.hostOneShotOnly = true;
}

/**
 * (#3673/#4241) Closure representation constants and header field factories.
 *
 * These now live in the LEAF module `closure-header-layout.ts` and are
 * re-exported here so the ~10 existing importers are unaffected. The move was
 * forced by a real failure: this module formerly imported the codegen barrel
 * (`../index.js`), and `program-abi-type-planning.ts` — which VALIDATES the
 * header on the IR path — was reachable from that barrel, so it could not import
 * the constants without closing an initialization cycle. It therefore carried
 * its own hand-written copy of the layout (`fields.length === 2 && funcref &&
 * i32`), which the `$bag` insertion silently invalidated. A leaf that both
 * sides can import is the fix; see that module's header for the full story.
 *
 * Capture fields start at CLOSURE_CAPTURE_FIELD_BASE — every capture
 * read/write, TDZ-slot index AND header validator derives from these
 * constants, never a bare literal.
 */
export {
  CLOSURE_ARITY_FIELD_IDX,
  CLOSURE_BAG_FIELD_IDX,
  CLOSURE_CAPTURE_FIELD_BASE,
  CLOSURE_FUNC_FIELD_IDX,
  closureArityField,
  closureBagField,
  closureBagInitInstr,
  closureSubtypeFieldCount,
  hasClosureHeaderPrefix,
  isCanonicalClosureHeader,
} from "./closure-header-layout.js";

/**
 * Look up a function's parameter and result types from its index.
 */
export function getFuncSignature(
  ctx: CodegenContext,
  funcIdx: number,
): { params: ValType[]; results: ValType[] } | null {
  // #1916 S2 — funcSignatureOf is the positional-read chokepoint (func-space.ts).
  const sig = funcSignatureOf(ctx, funcIdx);
  return sig ? { params: sig.params, results: sig.results } : null;
}

/**
 * Get or create the closure struct type and lifted func type for wrapping
 * plain functions with a given signature. Struct type and func type are shared
 * across all functions with the same signature, but each function gets its own
 * trampoline.
 */
export function getOrCreateFuncRefWrapperTypes(
  ctx: CodegenContext,
  userParams: ValType[],
  resultTypes: ValType[],
  allocationMode: ClosureAllocationMode = "ordinary",
): {
  structTypeIdx: number;
  liftedFuncTypeIdx: number;
  liftedSelfTypeIdx: number;
  closureInfo: ClosureInfo;
} | null {
  // Build cache key from param types and result types
  const sigKey = `${userParams.map((p) => p.kind + ((p as any).typeIdx ?? "")).join(",")}->${resultTypes.map((r) => r.kind + ((r as any).typeIdx ?? "")).join(",")}`;

  const cached = ctx.funcRefWrapperCache.get(sigKey);
  if (cached) {
    const observedMinimum = ctx.closureMinimumArgumentCountByFuncTypeIdx.get(cached.funcTypeIdx);
    if (observedMinimum !== undefined) {
      const current = cached.minimumArgumentCount ?? cached.paramTypes.length;
      cached.minimumArgumentCount = Math.min(current, observedMinimum);
    }
    observeAllocation(cached, allocationMode);
    return {
      structTypeIdx: cached.structTypeIdx,
      liftedFuncTypeIdx: cached.funcTypeIdx,
      liftedSelfTypeIdx: getFuncRefWrapperRootTypeIdx(ctx) ?? cached.structTypeIdx,
      closureInfo: cached,
    };
  }

  // Create the closure struct type: just (field $func funcref), no captures.
  // Mark as non-final (superTypeIdx = -1) so closures with captures can be
  // subtypes of this wrapper struct, enabling ref.cast to succeed at call sites.
  const closureName = `__fn_wrap_${ctx.closureCounter++}`;
  const structFields = [
    { name: "func", type: { kind: "funcref" as const }, mutable: false },
    closureArityField(),
    closureBagField(),
  ];
  const structTypeIdx = ctx.mod.types.length;
  const rootWrapperTypeIdx = (ctx as unknown as { __funcRefWrapperRootTypeIdx?: number }).__funcRefWrapperRootTypeIdx;
  ctx.mod.types.push({
    kind: "struct",
    name: `${closureName}_struct`,
    fields: structFields,
    superTypeIdx: rootWrapperTypeIdx ?? -1, // first wrapper is the root; later signatures subtype it
  });
  const liftedSelfTypeIdx = rootWrapperTypeIdx ?? structTypeIdx;
  if (rootWrapperTypeIdx === undefined) {
    (ctx as unknown as { __funcRefWrapperRootTypeIdx?: number }).__funcRefWrapperRootTypeIdx = structTypeIdx;
  }

  // Cross-module callable ABI: every lifted funcref takes the structurally
  // canonical ROOT as `self`, never the per-signature allocation wrapper.
  // Wrapper creation order is module-local, so embedding the latter here
  // makes identical source signatures disagree across separately compiled
  // modules. Captured bodies recover their environment with a root→subtype
  // cast; the user-visible params/results still identify the funcref exactly.
  const liftedParams: ValType[] = [{ kind: "ref", typeIdx: liftedSelfTypeIdx }, ...userParams];
  const liftedFuncTypeIdx = addFuncType(ctx, liftedParams, resultTypes, `${closureName}_type`);

  const closureInfo: ClosureInfo = {
    structTypeIdx,
    funcTypeIdx: liftedFuncTypeIdx,
    returnType: resultTypes.length > 0 ? resultTypes[0]! : null,
    paramTypes: userParams,
    minimumArgumentCount: ctx.closureMinimumArgumentCountByFuncTypeIdx.get(liftedFuncTypeIdx),
  };
  observeAllocation(closureInfo, allocationMode);
  ctx.closureInfoByTypeIdx.set(structTypeIdx, closureInfo);
  ctx.funcRefWrapperCache.set(sigKey, closureInfo);

  return { structTypeIdx, liftedFuncTypeIdx, liftedSelfTypeIdx, closureInfo };
}

/**
 * #3371 — Return a nominally-distinct subtype for an ordinary function value.
 *
 * Arrow functions and method closures deliberately keep using the signature
 * wrapper above.  Ordinary function declarations/expressions add one immutable
 * marker field, making their runtime type distinguishable for IsConstructor
 * without changing field 0 or the shared lifted-call ABI.  The subtype still
 * casts to the base wrapper at every existing call site.
 */
export function getOrCreateConstructibleFuncRefWrapperTypes(
  ctx: CodegenContext,
  userParams: ValType[],
  resultTypes: ValType[],
): {
  structTypeIdx: number;
  liftedFuncTypeIdx: number;
  liftedSelfTypeIdx: number;
  closureInfo: ClosureInfo;
} | null {
  const sigKey = `${userParams.map((p) => p.kind + ((p as any).typeIdx ?? "")).join(",")}->${resultTypes.map((r) => r.kind + ((r as any).typeIdx ?? "")).join(",")}`;
  const cached = ctx.constructibleFuncRefWrapperCache.get(sigKey);
  if (cached) {
    return {
      structTypeIdx: cached.structTypeIdx,
      liftedFuncTypeIdx: cached.funcTypeIdx,
      liftedSelfTypeIdx: getFuncRefWrapperRootTypeIdx(ctx) ?? cached.structTypeIdx,
      closureInfo: cached,
    };
  }

  const base = getOrCreateFuncRefWrapperTypes(ctx, userParams, resultTypes);
  if (!base) return null;
  const structTypeIdx = ctx.mod.types.length;
  ctx.mod.types.push({
    kind: "struct",
    name: `__constructible_fn_wrap_${ctx.closureCounter++}_struct`,
    fields: [
      { name: "func", type: { kind: "funcref" as const }, mutable: false },
      closureArityField(),
      closureBagField(),
      { name: "__constructible", type: { kind: "i32" as const }, mutable: false },
    ],
    superTypeIdx: base.structTypeIdx,
  });
  const closureInfo: ClosureInfo = {
    structTypeIdx,
    funcTypeIdx: base.liftedFuncTypeIdx,
    returnType: resultTypes.length > 0 ? resultTypes[0]! : null,
    paramTypes: userParams,
    minimumArgumentCount:
      ctx.closureMinimumArgumentCountByFuncTypeIdx.get(base.liftedFuncTypeIdx) ?? base.closureInfo.minimumArgumentCount,
  };
  ctx.closureInfoByTypeIdx.set(structTypeIdx, closureInfo);
  ctx.constructibleFuncRefWrapperCache.set(sigKey, closureInfo);
  ctx.constructibleClosureTypeIdxs.add(structTypeIdx);
  return {
    structTypeIdx,
    liftedFuncTypeIdx: base.liftedFuncTypeIdx,
    liftedSelfTypeIdx: base.liftedSelfTypeIdx,
    closureInfo,
  };
}

/**
 * Is `structTypeIdx` one of the SHARED per-signature wrappers (plain or
 * constructible)? Their records in `closureInfoByTypeIdx` describe every
 * captureless allocation of the signature at once, so a `hasRestParam` flag on
 * them cannot single out any one function (#5334).
 */
export function isSharedSignatureWrapperStruct(ctx: CodegenContext, structTypeIdx: number): boolean {
  for (const cache of [ctx.funcRefWrapperCache, ctx.constructibleFuncRefWrapperCache]) {
    for (const info of cache.values()) if (info.structTypeIdx === structTypeIdx) return true;
  }
  return false;
}

/**
 * (#4616) Get-or-create the rest-marker subtype of a funcref-wrapper struct:
 * the base wrapper's fields plus one immutable f64 marker. The f64 (vs the
 * constructible subtype's i32 marker) keeps the canonical shape distinct, so
 * `ref.test` can discriminate rest-param singleton closures at dispatch time.
 */
export function ensureRestFnWrapSubtype(ctx: CodegenContext, baseStructTypeIdx: number): number {
  const holder = ctx as unknown as { __restFnWrapSubtypeByBase?: Map<number, number> };
  const cache = (holder.__restFnWrapSubtypeByBase ??= new Map());
  const hit = cache.get(baseStructTypeIdx);
  if (hit !== undefined) return hit;
  const baseDef = ctx.mod.types[baseStructTypeIdx];
  const baseFields = baseDef?.kind === "struct" ? baseDef.fields : [];
  const idx = ctx.mod.types.length;
  ctx.mod.types.push({
    kind: "struct",
    name: `__rest_fn_wrap_${ctx.closureCounter++}_struct`,
    fields: [...baseFields, { name: "__rest_marker", type: { kind: "f64" as const }, mutable: false }],
    superTypeIdx: baseStructTypeIdx,
  });
  cache.set(baseStructTypeIdx, idx);
  return idx;
}

/**
 * (#5334) Pre-register the rest-marker allocation subtypes a rest DECLARATION's
 * cached singleton (`ensureFuncClosureSingleton`) will allocate, so a call site
 * compiled BEFORE the declaration's first value read — in an earlier source
 * file, say — already knows the struct whose `ref.test` proves the rest
 * reading. The singleton keys the marker on the wrapper it was asked for, and
 * its callers do not all agree on constructibility (#4491 T12), so both bases
 * are registered for an ordinary (constructible) declaration. Async and
 * generator declarations are left alone: their singleton wraps a different
 * result. Types only: no trampoline, no global, no function index moves.
 */
export function registerRestDeclarationWrapperShapes(
  ctx: CodegenContext,
  declaration: ts.FunctionDeclaration,
  userParams: ValType[],
  resultTypes: ValType[],
): void {
  if (
    userParams.length === 0 ||
    declaration.asteriskToken !== undefined ||
    (declaration.modifiers?.some((modifier) => modifier.kind === ts.SyntaxKind.AsyncKeyword) ?? false) ||
    !declaration.parameters.some((parameter) => parameter.dotDotDotToken !== undefined)
  ) {
    return;
  }
  const plain = getOrCreateFuncRefWrapperTypes(ctx, userParams, resultTypes, "support");
  if (!plain) return;
  const bases = [plain.structTypeIdx];
  const marked = getOrCreateConstructibleFuncRefWrapperTypes(ctx, userParams, resultTypes);
  if (marked) bases.push(marked.structTypeIdx);
  for (const base of bases) {
    const restIdx = ensureRestFnWrapSubtype(ctx, base);
    if (!ctx.closureInfoByTypeIdx.has(restIdx)) {
      ctx.closureInfoByTypeIdx.set(restIdx, {
        structTypeIdx: restIdx,
        funcTypeIdx: plain.liftedFuncTypeIdx,
        returnType: resultTypes.length > 0 ? resultTypes[0]! : null,
        paramTypes: userParams,
        hasRestParam: true,
      });
    }
    if (base !== plain.structTypeIdx) ctx.constructibleClosureTypeIdxs.add(restIdx);
  }
}

/**
 * (#2873 park fix) The ROOT funcref-wrapper struct type — the FIRST wrapper
 * `getOrCreateFuncRefWrapperTypes` created in this module. Every later
 * per-signature wrapper struct is a direct subtype of it. It is also the
 * canonical lifted-function `self` type for EVERY signature, so function type
 * identity does not depend on which signature created the root locally. The
 * finalization pass explicitly keeps this root open even in a minimal module
 * with no child wrapper: WasmGC canonical identity includes finality, so an
 * opportunistically-final root would not match another module's open root.
 * The root is therefore the ONLY wrapper type a `ref.test`/`ref.cast` is
 * guaranteed to accept for a closure value of ANY shared signature wrapper.
 *
 * Why callers need it: wrapper structs are all layout-identical
 * `(struct (field funcref))`, but WasmGC isorecursive canonicalization keys on
 * (fields, supertype, finality) — a direct `$root` subtype does NOT canonicalize
 * with the root or with another sibling. A call site that casts a
 * closure value to the wrapper of its *declared* signature therefore nulls out
 * whenever the value was allocated under a different signature's wrapper
 * (e.g. an activated async closure: its wrapper is minted for the REWRITTEN
 * `... -> externref` Promise signature, while an `fn: () => void` param casts
 * to the void wrapper) — unless creation ORDER happened to make the declared
 * wrapper the root. Cast/read/pass `self` through the root instead and
 * discriminate only on the funcref's exact type (which encodes the true
 * signature).
 */
export function getFuncRefWrapperRootTypeIdx(ctx: CodegenContext): number | undefined {
  return (ctx as unknown as { __funcRefWrapperRootTypeIdx?: number }).__funcRefWrapperRootTypeIdx;
}

/**
 * Return the concrete struct type used by a closure funcref's leading `self`
 * parameter. Shared wrapper funcs return the canonical root; private/named
 * function-expression funcs return their concrete nullable struct. Dispatch
 * sites use this distinction to avoid foreign per-signature wrapper casts
 * without breaking private closure types.
 */
export function getClosureFuncSelfTypeIdx(ctx: CodegenContext, funcTypeIdx: number): number | undefined {
  const type = ctx.mod.types[funcTypeIdx];
  if (!type || type.kind !== "func") return undefined;
  const self = type.params[0];
  return self && (self.kind === "ref" || self.kind === "ref_null") ? self.typeIdx : undefined;
}

// Copyright (c) 2026 Loopdive GmbH. Licensed under Apache-2.0 WITH LLVM-exception.
/**
 * (#2896) Standalone native function-object metadata.
 *
 * A builtin function value under `--target standalone` is a closure wrapper
 * struct (`getOrCreateFuncRefWrapperTypes`); it carries no `name`/`length`, so
 * every REFLECTIVE read (`Object.getOwnPropertyDescriptor(fn, "name")`,
 * `fn[key]` with a runtime key, `hasOwnProperty`, `getOwnPropertyNames`) sees
 * nothing — which fails test262's `propertyHelper.js verifyProperty` for every
 * builtin `name.js` / `length.js` / `prop-desc.js` even where a compile-time
 * direct-access meta fold exists (the helper's receiver/key are runtime params).
 *
 * ## Mechanism — per-(builtin, member) meta SUBTYPE, constant metadata per type
 *
 * For each distinct builtin function we materialize, register a UNIQUE struct
 * subtype of its signature wrapper:
 *
 *   `$__builtinfn_<n> {
 *      funcref func;
 *      (mut i32) bfnstate;
 *      i32 bfnid;
 *    } <: $__fn_wrap_<sig>`
 *
 * - Being a SUBTYPE of the signature wrapper keeps every existing call path
 *   working untouched (static closure calls, reflective `.call`, any-typed
 *   callback dispatch — they cast to the sig wrapper / root, and a subtype
 *   passes).
 * - The metadata itself ({name, length}) is statically known per (builtin,
 *   member), so it lives in `ctx.builtinFnMetaByTypeIdx` keyed by the meta type
 *   index. WasmGC structurally canonicalizes the otherwise-identical meta
 *   subtypes, so `ref.test <metaType>` is not an identity discriminator. The
 *   immutable `bfnid` field anchors each instance to its exact metadata entry;
 *   reflective natives require both the family `ref.test` and matching id.
 * - `bfnstate` is the one piece of per-INSTANCE state: a deleted-bits mask
 *   (bit 0 = `name` deleted, bit 1 = `length` deleted). `verifyProperty`'s
 *   `isConfigurable` arm `delete`s the property and then requires
 *   `hasOwnProperty` to report false, so delete must genuinely work.
 *   `struct.new` sites therefore push an extra `i32.const 0`
 *   (`pushBuiltinFnClosureValueInstrs` below).
 */
import type { Instr, ValType } from "../ir/types.js";
import type { ClosureInfo, CodegenContext, FunctionContext } from "./context/types.js";
import {
  closureArityField,
  closureBagField,
  closureBagInitInstr,
  getOrCreateFuncRefWrapperTypes,
} from "./closures/funcref-wrapper-types.js";
import { mintDefinedFunc, pushDefinedFunc } from "./func-space.js";

/**
 * (#4241) Field indices of the meta-typed closure subtype, derived from the
 * shared closure header rather than spelled as bare literals — the header grew
 * a `$bag` slot at index 2 and these two shifted with it.
 * Layout: `[func, $arity, $bag, bfnstate, bfnid]`.
 */
export const BFN_STATE_FIELD_IDX = 3;
export const BFN_ID_FIELD_IDX = 4;

/**
 * Spec `{name, length}` for the builtin STATIC method closures wired in
 * `ensureStandaloneBuiltinStaticMethodClosure` (property-access.ts). Keep in
 * sync with its `switch (key)`. Also consumed by the direct-access
 * `.name`/`.length` meta fold so the constant fold and the runtime descriptor
 * agree.
 */
export const STANDALONE_STATIC_METHOD_META: Record<string, { name: string; length: number }> = {
  "Array.isArray": { name: "isArray", length: 1 },
  "Object.assign": { name: "assign", length: 2 },
  "Object.keys": { name: "keys", length: 1 },
  "Object.getOwnPropertyDescriptor": { name: "getOwnPropertyDescriptor", length: 2 },
  // (#2933) Fixed-arity Reflect.* namespace static-method value reads. Spec
  // `length` per §28.1 (receiver arg is optional and not counted).
  "Reflect.get": { name: "get", length: 2 },
  "Reflect.has": { name: "has", length: 2 },
  "Reflect.set": { name: "set", length: 3 },
  "Reflect.ownKeys": { name: "ownKeys", length: 1 },
  "Reflect.getOwnPropertyDescriptor": { name: "getOwnPropertyDescriptor", length: 2 },
  "Reflect.defineProperty": { name: "defineProperty", length: 3 },
  // (#2933) JSON.stringify as a VALUE — the fixed 1-arg compact form. The value
  // closure serialises via the native `__json_stringify_root` (host-free), the
  // SAME entry the direct `JSON.stringify(o)` call path uses. Spec `.length` is
  // 3 (value, replacer, space); the host-free closure supports only the leading
  // value arg (replacer/space out of scope, matching the standalone call-path
  // narrowing), but `.length` reports the spec arity.
  "JSON.stringify": { name: "stringify", length: 3 },
  "Symbol.for": { name: "for", length: 1 },
  "Symbol.keyFor": { name: "keyFor", length: 1 },
  "Promise.resolve": { name: "resolve", length: 1 },
  "Promise.reject": { name: "reject", length: 1 },
  // (#2933) Math.max/Math.min as VALUES — genuinely VARIADIC; reified with the
  // canonical variadic closure convention (one `$vec_externref` args param, see
  // `ctx.variadicBuiltinClosure`). Spec `.length` is 2 for both (§21.3.2.24/.25).
  "Math.max": { name: "max", length: 2 },
  "Math.min": { name: "min", length: 2 },
  // (#2963 Tier 2a) Number.is* fixed 1-arg predicates as VALUES. `.name` === the
  // property key (§10.2.9); `.length` 1 (§21.1.2.x). These agree byte-for-byte
  // with the generic `BUILTIN_STATIC_METHOD_ARITY` fallback, listed explicitly
  // per the file-header sync rule for newly-wired closures.
  "Number.isInteger": { name: "isInteger", length: 1 },
  "Number.isFinite": { name: "isFinite", length: 1 },
  "Number.isNaN": { name: "isNaN", length: 1 },
  "Number.isSafeInteger": { name: "isSafeInteger", length: 1 },
  // (#2963 Tier 2b) Object.is fixed 2-arg SameValue as a VALUE (§20.1.2.13).
  "Object.is": { name: "is", length: 2 },
};

/**
 * (#2896) Spec arity of every standard builtin STATIC method (own
 * function-valued data properties of the global constructors/namespaces), for
 * the direct-access `<Builtin>.<method>.length` / `.name` meta fold. `.name`
 * equals the property key for all of these (§10.2.9); `.length` values are the
 * ECMA-262 declared arities (generated from a conforming host — V8/Node — and
 * spot-checked against the spec). This is a compile-time COMPANION of the
 * runtime metadata substrate above: the fold answers direct syntactic reads
 * (no closure materialization, so it also covers methods whose value-read is
 * not yet wired host-free); the meta subtypes answer reflective/runtime reads
 * for the wired closures.
 *
 * (#3181) The whole table AND every inner record are NULL-PROTOTYPED via
 * `nullProtoDeep`. A plain object literal inherits `Object.prototype`, so an
 * inner lookup of an `Object.prototype` method name (`toString`/`valueOf`/
 * `hasOwnProperty`/`constructor`…) returned the INHERITED FUNCTION rather than
 * `undefined` — making the fold at property-access.ts:1126 treat e.g.
 * `Number.toString.length` as "found" and emit the `Function` as an f64 → NaN.
 * With null prototypes, only the explicitly-listed static methods match; every
 * other name resolves `undefined` and routes through the normal path.
 */
const nullProtoDeep = (rec: Record<string, Record<string, number>>): Record<string, Record<string, number>> => {
  const out: Record<string, Record<string, number>> = Object.create(null);
  for (const key of Object.keys(rec)) {
    out[key] = Object.assign(Object.create(null) as Record<string, number>, rec[key]);
  }
  return out;
};

